package com.college.hospitalmanagement;import com.college.hospitalmanagement.dto.*;import jakarta.validation.Valid;import java.net.URI;import java.util.*;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") public class BedManagementController{private final BedManagementService s;public BedManagementController(BedManagementService s){this.s=s;}@GetMapping("/wards")public List<WardResponseDTO> wards(){return s.wards();}@GetMapping("/wards/{id}")public WardResponseDTO ward(@PathVariable Long id){return s.ward(id);}@PostMapping("/wards")public ResponseEntity<WardResponseDTO> addWard(@Valid @RequestBody WardRequestDTO r){WardResponseDTO x=s.createWard(r);return ResponseEntity.created(URI.create("/api/wards/"+x.id())).body(x);}@PutMapping("/wards/{id}")public WardResponseDTO editWard(@PathVariable Long id,@Valid @RequestBody WardRequestDTO r){return s.updateWard(id,r);}@DeleteMapping("/wards/{id}")public ResponseEntity<Void> delWard(@PathVariable Long id){s.deleteWard(id);return ResponseEntity.noContent().build();}@GetMapping("/rooms")public List<RoomResponseDTO> rooms(){return s.rooms();}@GetMapping("/rooms/{id}")public RoomResponseDTO room(@PathVariable Long id){return s.room(id);}@PostMapping("/rooms")public ResponseEntity<RoomResponseDTO> addRoom(@Valid @RequestBody RoomRequestDTO r){RoomResponseDTO x=s.createRoom(r);return ResponseEntity.created(URI.create("/api/rooms/"+x.id())).body(x);}@PutMapping("/rooms/{id}")public RoomResponseDTO editRoom(@PathVariable Long id,@Valid @RequestBody RoomRequestDTO r){return s.updateRoom(id,r);}@DeleteMapping("/rooms/{id}")public ResponseEntity<Void> delRoom(@PathVariable Long id){s.deleteRoom(id);return ResponseEntity.noContent().build();}@GetMapping("/beds")public List<BedResponseDTO> beds(){return s.beds();}@GetMapping("/beds/{id}")public BedResponseDTO bed(@PathVariable Long id){return s.bed(id);}@PostMapping("/beds")public ResponseEntity<BedResponseDTO> addBed(@Valid @RequestBody BedRequestDTO r){BedResponseDTO x=s.createBed(r);return ResponseEntity.created(URI.create("/api/beds/"+x.id())).body(x);}@PutMapping("/beds/{id}")public BedResponseDTO editBed(@PathVariable Long id,@Valid @RequestBody BedRequestDTO r){return s.updateBed(id,r);}@DeleteMapping("/beds/{id}")public ResponseEntity<Void> delBed(@PathVariable Long id){s.deleteBed(id);return ResponseEntity.noContent().build();}@PostMapping("/beds/{id}/allocate")public BedResponseDTO allocate(@PathVariable Long id,@Valid @RequestBody BedAllocationRequestDTO r){return s.allocate(id,r);}@PostMapping("/beds/{id}/discharge")public BedResponseDTO discharge(@PathVariable Long id){return s.discharge(id);}}
